  async _drop(progress: Progress, inputFileItems: InputFilesItems, data: { mimeType: string, value: string }[], options: { position?: types.Point }, frameVisible: boolean): Promise<'error:notconnected' | 'done'> {
    const { filePayloads, localPaths } = inputFileItems;
    let payloads: { name: string, mimeType: string, buffer: string, lastModifiedMs?: number }[];
    if (localPaths && !filePayloads) {
      // Co-located server/browser: read files into buffers so File objects can be
      // constructed in page context.
      payloads = await Promise.all(localPaths.map(async p => ({
        name: path.basename(p),
        mimeType: mime.getType(p) || 'application/octet-stream',
        buffer: (await fs.promises.readFile(p)).toString('base64'),
        lastModifiedMs: (await fs.promises.stat(p)).mtimeMs,
      })));
    } else {
      payloads = (filePayloads ?? []).map(p => ({
        name: p.name,
        mimeType: p.mimeType || 'application/octet-stream',
        buffer: p.buffer,
        lastModifiedMs: p.lastModifiedMs,
      }));
    }
    const perform = async (progress: Progress, point: types.Point) => {
      // Firefox strips files from DataTransfer objects that cross the isolated-world
      // boundary into the page's main world. Adopt the element to main context and
      // construct the DataTransfer + dispatch events there.
      const mainContext = await progress.race(this._frame.mainContext());
      const handle = this._context === mainContext ? this : await progress.race(this._page.delegate.adoptElementHandle(this, mainContext));
      const disposeHandle = handle !== this;
      try {
        const result = await progress.race(handle.evaluate((node: Node, { payloads, data, point }) => {
          if (!node.isConnected || node.nodeType !== 1 /* ELEMENT_NODE */)
            return 'error:notconnected' as const;
          const element = node as Element;
          const dt = new DataTransfer();
          for (const p of payloads) {
            const bytes = Uint8Array.from(atob(p.buffer), c => c.charCodeAt(0));
            const file = new File([bytes], p.name, { type: p.mimeType, lastModified: p.lastModifiedMs });
            dt.items.add(file);
          }
          for (const entry of data)
            dt.setData(entry.mimeType, entry.value);
          const makeEvent = (type: string) => new DragEvent(type, {
            bubbles: true,
            cancelable: true,
            composed: true,
            clientX: point.x,
            clientY: point.y,
            dataTransfer: dt,
          });
          element.dispatchEvent(makeEvent('dragenter'));
          const over = makeEvent('dragover');
          element.dispatchEvent(over);
          if (!over.defaultPrevented) {
            element.dispatchEvent(makeEvent('dragleave'));
            return 'not-accepted' as const;
          }
          element.dispatchEvent(makeEvent('drop'));
          return 'accepted' as const;
        }, { payloads, data, point }));
        if (result === 'not-accepted')
          throw new NonRecoverableDOMError('Drop target did not accept the drop — its dragover handler did not call preventDefault()');
      } finally {
        if (disposeHandle)
          handle.dispose();
      }
    };
    return this._retryPointerAction(progress, { name: 'drop', waitForEnabled: false, waitAfter: 'disabled', perform }, options, frameVisible);
  }

  async _setInputFiles(progress: Progress, items: InputFilesItems, box?: types.Rect): Promise<'error:notconnected' | 'done'> {
    const { filePayloads, localPaths, localDirectory } = items;
    const multiple = filePayloads && filePayloads.length > 1 || localPaths && localPaths.length > 1;
    const result = await progress.race(this._evaluateHandleInUtility(([injected, node, { multiple, directoryUpload }]): Element | undefined => {
      const element = injected.retarget(node, 'follow-label');
      if (!element)
        return;
      if (element.tagName !== 'INPUT')
        throw injected.createStacklessError('Node is not an HTMLInputElement');
      const inputElement = element as HTMLInputElement;
      if (multiple && !inputElement.multiple && !inputElement.webkitdirectory)
        throw injected.createStacklessError('Non-multiple file input can only accept single file');
      if (directoryUpload && !inputElement.webkitdirectory)
        throw injected.createStacklessError('File input does not support directories, pass individual files instead');
      if (!directoryUpload && inputElement.webkitdirectory)
        throw injected.createStacklessError('[webkitdirectory] input requires passing a path to a directory');
      return inputElement;
    }, { multiple, directoryUpload: !!localDirectory }));
    if (result === 'error:notconnected' || !result.asElement())
      return 'error:notconnected';
    const retargeted = result.asElement() as ElementHandle<HTMLInputElement>;
    await this.instrumentation.onBeforeInputAction(progress, this, undefined, box);
    if (localPaths || localDirectory) {
      const localPathsOrDirectory = localDirectory ? [localDirectory] : localPaths!;
      await progress.race(Promise.all((localPathsOrDirectory).map(localPath => (
        fs.promises.access(localPath, fs.constants.F_OK)
      ))));
      // Browsers traverse the given directory asynchronously and we want to ensure all files are uploaded.
      const waitForInputEvent = localDirectory ? this.evaluate(node => new Promise<any>(fulfill => {
        node.addEventListener('input', fulfill, { once: true });
      })).catch(() => {}) : Promise.resolve();
      await this._page.delegate.setInputFilePaths(progress, retargeted, localPathsOrDirectory);
      await progress.race(waitForInputEvent);
    } else {
      await progress.race(retargeted.evaluateInUtility(([injected, node, files]) =>
        injected.setInputFiles(node, files), filePayloads!));
    }
    return 'done';
  }

