  async _setChecked(progress: Progress, state: boolean, options: { position?: types.Point } & types.PointerActionWaitOptions, frameVisible: boolean): Promise<'error:notconnected' | 'done'> {
    const isChecked = async (progress: Progress) => {
      const result = await progress.race(this.evaluateInUtility(([injected, node]) => injected.elementState(node, 'checked'), {}));
      if (result === 'error:notconnected' || result.received === 'error:notconnected')
        throwElementIsNotAttached();
      return { matches: result.matches, isRadio: result.isRadio };
    };
    await this._markAsTargetElement(progress);
    const checkedState = await isChecked(progress);
    if (checkedState.matches === state)
      return 'done';
    if (!state && checkedState.isRadio)
      throw new NonRecoverableDOMError('Cannot uncheck radio button. Radio buttons can only be unchecked by selecting another radio button in the same group.');
    const result = await this._click(progress, options, 'disabled', frameVisible);
    if (result !== 'done')
      return result;
    if (options.trial)
      return 'done';
    const finalState = await isChecked(progress);
    if (finalState.matches !== state)
      throw new NonRecoverableDOMError('Clicking the checkbox did not change its state');
    return 'done';
  }

  async boundingBox(progress: Progress): Promise<types.Rect | null> {
    return await progress.race(this._page.delegate.getBoundingBox(this));
  }

  async screenshot(progress: Progress, options: ScreenshotOptions): Promise<Buffer> {
    return await this._page.screenshotter.screenshotElement(progress, this, options, true /* frameVisible */);
  }

  async querySelector(progress: Progress, target: types.SelectorTarget): Promise<ElementHandle | null> {
    return progress.race(this._frame.selectors.query({ ...target, scope: this }));
  }

  async querySelectorAll(progress: Progress, selector: string): Promise<ElementHandle<Element>[]> {
    return progress.race(this._querySelectorAll(selector));
  }

  private async _querySelectorAll(selector: string): Promise<ElementHandle<Element>[]> {
    return this._frame.selectors.queryAll(selector, this);
  }

  override async evaluateExpression(progress: Progress, expression: string, options: { isFunction?: boolean, world?: types.World, serialize?: ('Map' | 'Set')[] }, arg: any): Promise<any> {
    return await progress.race(this.internalEvaluateExpression(expression, options, arg));
  }

  override async internalEvaluateExpression(expression: string, options: { isFunction?: boolean, world?: types.World, serialize?: ('Map' | 'Set')[] }, arg: any): Promise<any> {
    const context = options.world ? await this._frame.context(options.world) : this._context;
    return await js.evaluateExpression(context, expression, { isFunction: options.isFunction, serialize: options.serialize, returnByValue: true }, this, arg);
  }

  async evalOnSelector(progress: Progress, target: types.SelectorTarget, expression: string, options: { isFunction?: boolean, world?: types.World }, arg: any): Promise<any> {
    return this._frame.evalOnSelector(progress, { ...target, scope: this }, expression, options, arg);
  }

  async evalOnSelectorAll(progress: Progress, selector: string, expression: string, options: { isFunction?: boolean, world?: types.World }, arg: any): Promise<any> {
    return this._frame.evalOnSelectorAll(progress, selector, expression, options, arg, this);
  }

  async isVisible(progress: Progress): Promise<boolean> {
    return this._frame.isVisible(progress, { selector: ':scope', scope: this });
  }

  async isHidden(progress: Progress): Promise<boolean> {
    return this._frame.isHidden(progress, { selector: ':scope', scope: this });
  }

  async isEnabled(progress: Progress): Promise<boolean> {
    return this._frame.isEnabled(progress, { selector: ':scope', scope: this });
  }

  async isDisabled(progress: Progress): Promise<boolean> {
    return this._frame.isDisabled(progress, { selector: ':scope', scope: this });
  }

  async isEditable(progress: Progress): Promise<boolean> {
    return this._frame.isEditable(progress, { selector: ':scope', scope: this });
  }

  async isChecked(progress: Progress): Promise<boolean> {
    return this._frame.isChecked(progress, { selector: ':scope', scope: this });
  }

  async waitForElementState(progress: Progress, state: 'visible' | 'hidden' | 'stable' | 'enabled' | 'disabled' | 'editable'): Promise<void> {
    const actionName = `wait for ${state}`;
    const result = await this._retryAction(progress, actionName, async progress => {
      return await progress.race(this.evaluateInUtility(async ([injected, node, state]) => {
        return (await injected.checkElementStates(node, [state], true /* frameVisible */)) || 'done';
      }, state));
    }, {});
    assertDone(throwRetargetableDOMError(result));
  }

  async waitForSelector(progress: Progress, target: types.SelectorTarget, options: types.WaitForElementOptions): Promise<ElementHandle<Element> | null> {
    return await this._frame.waitForSelector(progress, { ...target, scope: this }, true, options);
  }

  async _adoptTo(context: FrameExecutionContext): Promise<ElementHandle<T>> {
    if (this._context !== context) {
      const adopted = await this._page.delegate.adoptElementHandle(this, context);
      this.dispose();
      return adopted;
    }
    return this;
  }

  async _checkFrameIsHitTarget(progress: Progress, point: types.Point): Promise<{ framePoint: types.Point | undefined } | 'error:notconnected' | { hitTargetDescription: string }> {
    let frame = this._frame;
    const data: { frame: frames.Frame, frameElement: ElementHandle<Element> | null, pointInFrame: types.Point }[] = [];
    const temporaryFrameElements: ElementHandle<Element>[] = [];
    try {
      while (frame.parentFrame()) {
        const frameElement = await frame.frameElement(progress) as ElementHandle<Element>;
        temporaryFrameElements.push(frameElement);
        const box = await frameElement.boundingBox(progress);
        const style = await progress.race(frameElement.evaluateInUtility(([injected, iframe]) => injected.describeIFrameStyle(iframe), {}).catch(e => 'error:notconnected' as const));
        if (!box || style === 'error:notconnected')
          return 'error:notconnected';
        if (style === 'transformed') {
          // We cannot translate coordinates when iframe has any transform applied.
          // The best we can do right now is to skip the hitPoint check,
          // and solely rely on the event interceptor.
          return { framePoint: undefined };
        }
        // Translate from viewport coordinates to frame coordinates.
        const pointInFrame = { x: point.x - box.x - style.left, y: point.y - box.y - style.top };
        data.push({ frame, frameElement, pointInFrame });
        frame = frame.parentFrame()!;
      }
      // Add main frame.
      data.push({ frame, frameElement: null, pointInFrame: point });

      for (let i = data.length - 1; i > 0; i--) {
        const element = data[i - 1].frameElement!;
        const point = data[i].pointInFrame;
        // Hit target in the parent frame should hit the child frame element.
        const hitTargetResult = await progress.race(element.evaluateInUtility(([injected, element, hitPoint]) => {
          return injected.expectHitTarget(hitPoint, element);
        }, point));
        if (hitTargetResult !== 'done')
          return hitTargetResult;
      }
      return { framePoint: data[0].pointInFrame };
    } finally {
      for (const frameElement of temporaryFrameElements)
        frameElement.dispose();
    }
  }
}

export function throwRetargetableDOMError<T>(result: T | 'error:notconnected'): T {
  if (result === 'error:notconnected')
    throwElementIsNotAttached();
  return result;
}

export function throwElementIsNotAttached(): never {
  throw new Error('Element is not attached to the DOM');
}

export function assertDone(result: 'done'): void {
  // This function converts 'done' to void and ensures typescript catches unhandled errors.
}

function roundPoint(point: types.Point): types.Point {
  return {
    x: (point.x * 100 | 0) / 100,
    y: (point.y * 100 | 0) / 100,
  };
}

function quadToRect(quad: types.Quad): types.Rect {
  let minX = Infinity;
  let minY = Infinity;
  let maxX = -Infinity;
  let maxY = -Infinity;
  for (const point of quad) {
    minX = Math.min(minX, point.x);
    minY = Math.min(minY, point.y);
    maxX = Math.max(maxX, point.x);
    maxY = Math.max(maxY, point.y);
  }
  return { x: minX, y: minY, width: maxX - minX, height: maxY - minY };
}

function quadMiddlePoint(quad: types.Quad): types.Point {
  const result = { x: 0, y: 0 };
  for (const point of quad) {
    result.x += point.x / 4;
    result.y += point.y / 4;
  }
  return result;
}

function triangleArea(p1: types.Point, p2: types.Point, p3: types.Point): number {
  return Math.abs(p1.x * (p2.y - p3.y) + p2.x * (p3.y - p1.y) + p3.x * (p1.y - p2.y)) / 2;
}

function isPointInsideQuad(point: types.Point, quad: types.Quad): boolean {
  const area1 = triangleArea(point, quad[0], quad[1]) + triangleArea(point, quad[1], quad[2]) + triangleArea(point, quad[2], quad[3]) + triangleArea(point, quad[3], quad[0]);
  const area2 = triangleArea(quad[0], quad[1], quad[2]) + triangleArea(quad[1], quad[2], quad[3]);
  // Check that point is inside the quad.
  if (Math.abs(area1 - area2) > 0.1)
    return false;
  // Check that point is not on the right/bottom edge, because clicking
  // there does not actually click the element.
  return point.x < Math.max(quad[0].x, quad[1].x, quad[2].x, quad[3].x) &&
         point.y < Math.max(quad[0].y, quad[1].y, quad[2].y, quad[3].y);
}

function findIntegerPointInsideQuad(quad: types.Quad): types.Point | undefined {
  // Try all four rounding directions of the middle point.
  const point = quadMiddlePoint(quad);
  point.x = Math.floor(point.x);
  point.y = Math.floor(point.y);
  if (isPointInsideQuad(point, quad))
    return point;
  point.x += 1;
  if (isPointInsideQuad(point, quad))
    return point;
  point.y += 1;
  if (isPointInsideQuad(point, quad))
    return point;
  point.x -= 1;
  if (isPointInsideQuad(point, quad))
    return point;
}

export const kUnableToAdoptErrorMessage = 'Unable to adopt element handle from a different document';
